"""Two self-contained offline reports; all built images are derived from final NBT."""
from pathlib import Path
import os,json,base64,zlib,re,io,html,shutil,ast
from PIL import Image
C=Path(__file__).resolve().parents[1];ROOT=C.parents[1];RUN=os.environ.get('ESTATE_RUN','V1_r06');R=C/'runs'/RUN;P=C/'review/previews'/RUN;OUT=Path(os.environ.get('ESTATE_OUTPUT',str(ROOT/'deliverables/estate')));OUT.mkdir(parents=True,exist_ok=True)
load=lambda p:json.loads(Path(p).read_text());PAR=load(R/'params_used.json');MAN=load(R/'manifest.json');VAL=load(R/'validation.json');ACC=load(R/'access_validation.json');LAY=load(R/'layout_validation.json');META=load(P/'scene/scene.json')
esc=lambda s:html.escape(str(s),quote=True)
def data(p,mime=None):
 p=Path(p);mime=mime or {'.png':'image/png','.jpg':'image/jpeg','.json':'application/json'}.get(p.suffix,'application/octet-stream');return 'data:'+mime+';base64,'+base64.b64encode(p.read_bytes()).decode()
def pic(p,size=1600):
 im=Image.open(p).convert('RGB');im.thumbnail((size,size));f=io.BytesIO();im.save(f,'WEBP',quality=91);return 'data:image/webp;base64,'+base64.b64encode(f.getvalue()).decode()
def dl(p,label=None):return '<a class="btn" download="'+esc(Path(p).name)+'" href="'+data(p)+'">'+esc(label or Path(p).name)+'</a>'
def fig(name,title,desc='',folder=P):return '<figure><a href="'+data(folder/name)+'" download="'+name+'"><img loading="lazy" src="'+pic(folder/name)+'" alt="'+esc(title)+'"></a><figcaption><b>'+esc(title)+'</b><span>'+esc(desc)+'</span></figcaption></figure>'
def table(head,rows):return '<div class="table"><table><tr>'+''.join('<th>'+esc(x)+'</th>' for x in head)+'</tr>'+''.join('<tr>'+''.join('<td>'+str(v)+'</td>' for v in row)+'</tr>' for row in rows)+'</table></div>'
def section(id,n,title,body):return '<section id="'+id+'"><div class="section-title"><small>'+n+'</small><h2>'+title+'</h2></div>'+body+'</section>'
CSS='''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f4f0e7;color:#303b31;font:15px/1.8 Noto,system-ui,sans-serif}header,main,footer{max-width:1280px;margin:auto;padding:0 32px}header{padding-top:44px}.eyebrow{font:12px monospace;letter-spacing:.15em;color:#916646}h1{font-size:clamp(36px,5vw,66px);font-weight:550;line-height:1.15;letter-spacing:-.04em;margin:24px 0}h2{font-size:29px;font-weight:550;line-height:1.4;margin:0}h3{font-size:20px;margin:0 0 12px}.intro{font-size:18px;max-width:780px;color:#66705f}.tags{margin:20px 0}.tag{display:inline-block;border:1px solid #c5b59f;border-radius:30px;padding:3px 13px;margin:0 8px 7px 0;font-size:12px}nav{display:flex;flex-wrap:wrap;gap:22px;padding:19px 0;border-top:1px solid #cfc5b4;border-bottom:1px solid #cfc5b4}a{color:#a25334;text-decoration:none}a:hover{text-decoration:underline}.hero{margin:28px 0}.hero img{width:100%;display:block;border-radius:4px}.hero p{font-size:12px;color:#687061}.stats{display:grid;grid-template-columns:repeat(4,1fr);border-top:1px solid #cec2ad;border-bottom:1px solid #cec2ad;padding:22px 0;gap:20px}.stat{font:38px/1.2 monospace;color:#754f34}.stats small{display:block;font-size:12px;color:#707969;margin-top:8px}section{padding:55px 0;border-bottom:1px solid #cec6b5;scroll-margin-top:20px}.section-title{display:flex;align-items:baseline;gap:24px;margin-bottom:28px}.section-title small{font:13px monospace;color:#9f5c3d}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px}.grid.three{grid-template-columns:repeat(3,minmax(0,1fr))}.card{background:#fffaf1;border:1px solid #d9ccba;padding:26px}.dark{background:#394b40;color:#f7f1e1;padding:30px;margin:28px 0}.dark p{color:#d2dfd1}.note{padding:18px 23px;border-left:3px solid #ad7650;background:#eae2d1;margin:24px 0}figure{margin:0;background:#fffaf1;border:1px solid #d9ccba;overflow:hidden}figure img{display:block;width:100%;height:420px;object-fit:contain;background:#dce1d5}figcaption{padding:16px 20px}figcaption b,figcaption span{display:block}figcaption span{font-size:12px;color:#6c7865;margin-top:5px}figure.wide img{height:auto}.table{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:13px}th,td{padding:14px 12px;border-bottom:1px solid #d2c9b7;text-align:left;vertical-align:top;min-width:100px}th{color:#795a41;font-weight:500}.btn,button,select{display:inline-block;border:1px solid #ae9980;background:#fffcf5;padding:8px 15px;color:#6f4a32;font:inherit;border-radius:3px;cursor:pointer;margin:4px 7px 4px 0}.primary{background:#74593d;color:#fff9ec}.controls{display:flex;align-items:center;flex-wrap:wrap;gap:15px;margin-bottom:18px}.controls input{accent-color:#8c643b}.pill{display:inline-block;background:#dce7d8;color:#48623d;padding:1px 8px;font:11px monospace}iframe{width:100%;height:760px;border:0;background:#1b302c}code,pre{font-family:monospace}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#e8e4d8;padding:20px;font-size:12px}details{padding:14px 0;border-bottom:1px solid #d5ccbc}summary{cursor:pointer}svg{max-width:100%;height:auto}footer{padding-top:30px;padding-bottom:40px;font-size:12px;color:#6b7767}.foot{font-size:12px;color:#687563}@media(max-width:760px){header,main,footer{padding-left:18px;padding-right:18px}.grid,.grid.three{grid-template-columns:1fr}.stats{grid-template-columns:repeat(2,1fr)}h2{font-size:24px}section{padding:38px 0}.card{padding:20px}figure img{height:340px}.section-title{gap:14px}iframe{height:660px}.btn{font-size:12px}.table{max-width:100%}}'''
def shell(title,sub,nav,body,script=''):
 return '<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+'</title><style>'+CSS+'</style></head><body><header><div class="eyebrow">GAFAcraft / HAF 0.4 · ORIGINAL RESIDENTIAL · 2026.10.27</div><h1>'+title+'</h1><p class="intro">'+sub+'</p><nav>'+''.join('<a href="#'+a+'">'+b+'</a>' for a,b in nav)+'</nav></header><main>'+body+'</main><footer>海扒拉 · HAF 0.4 · 千禧年住宅组团 '+RUN+'<br>方块几何与近似灯光预览；不是 Minecraft 游戏截图。原创建筑意向，不是现实建筑施工或合规方案。</footer><script>'+script.replace('</script','<\\/script')+'</script></body></html>'
def site_svg():
 s='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 800 850"><rect width="800" height="850" fill="#e7ecde"/><text x="30" y="32" font-size="18" fill="#415744">N ↑　模型北向 −Z</text><g transform="translate(18,40) scale(4.7)">'
 for x,z in load(R/'paths.json')['cells_xz']:s+=f'<rect x="{x}" y="{z}" width="1.1" height="1.1" fill="#d0bb94"/>'
 for t in PAR['towers']:
  x,z,w,d=t['x'],t['z'],t['w'],t['d'];s+=f'<rect x="{x}" y="{z}" width="{w}" height="{d}" rx=".7" fill="'+('#ba8e64' if t['type']=='A' else '#8a634c')+f'" stroke="#6c4b34" stroke-width=".4"/><text x="{x+w/2}" y="{z+10}" text-anchor="middle" font-size="4" fill="#fff7df">{t["id"]} · {t["storeys"]}F</text><text x="{x+w/2}" y="{z+16}" text-anchor="middle" font-size="2.8" fill="#fff7df">一梯{["一","二"][t["units_per_floor"]-1]}户</text>'
 for row in ['A','B']:
  ts=[t for t in PAR['towers'] if t['type']==row]
  for a,b in zip(ts,ts[1:]):
   xx=a['x']+a['w']+3;s+=f'<path d="M{xx} {a["z"]}V{b["z"]}H{b["x"]-2}" fill="none" stroke="#b35d3e" stroke-width=".6"/><text x="{xx+1}" y="{(a["z"]+b["z"])/2}" font-size="2.6" fill="#913f27">10 格</text>'
 s+='<text x="69" y="82" font-size="4" fill="#547344">斜向中央花园</text><text x="48" y="163" font-size="3" fill="#547344">入口</text></g></svg>';return s
def box_svg():
 s='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 760 460"><rect width="760" height="460" fill="#e8eadf"/>'
 def pr(x,y,z):return (380+(x-z)*1.8,130+(x+z)*.75-y*2)
 for t in PAR['towers']:
  x,z=t['x'],t['z'];pts=[(X,Y,Z) for Y in [3,3+t['storeys']*5] for Z in [z,z+t['d']] for X in [x,x+t['w']]]
  for i,a in enumerate(pts):
   for j,bb in enumerate(pts):
    if j>i and sum(a[k]!=bb[k] for k in range(3))==1:
     u,v=pr(*a);U,V=pr(*bb);s+=f'<path d="M{u} {v}L{U} {V}" stroke="#8c6b4a" fill="none" stroke-width="1.6"/>'
  u,v=pr(x+t['w']/2,5+t['storeys']*5,z+t['d']/2);s+=f'<text x="{u}" y="{v}" font-size="16" fill="#536548">{t["id"]}</text>'
 s+='<text x="28" y="430" font-size="16" fill="#65705a">8 个角点 / 楼栋包围盒 · 实际参数投影 · 无自动相机恢复</text></svg>';return s
def viewer():
 src=(ROOT/'support/templates/voxel_viewer.html').read_text();bins={n:base64.b64encode(zlib.compress((P/'scene'/n).read_bytes(),8)).decode() for n in ['opaque.bin','glass.bin','blocklight.bin']}
 src=re.sub(r'const BINS=.*?;\s*const META=.*?;\s*async function inflate',lambda m:'const BINS='+json.dumps(bins)+';\nconst META='+json.dumps(META)+';\nasync function inflate',src,flags=re.S)
 src=src.replace('市民服务中心 · NBT 几何查看','千禧年住宅 · NBT 查看')
 opts='<option value="all">整体</option><option value="top">俯视总图</option><option value="garden">花园切低</option><option value="floor">逐层内饰</option><option value="tower">单栋</option>'
 src=re.sub(r'<select id="mode">.*?</select>',lambda m:'<select id="mode">'+opts+'</select>',src,flags=re.S)
 controls='<label>楼栋 <select id="tower">'+''.join('<option value="'+t['id']+'">'+t['id']+'</option>' for t in PAR['towers'])+'</select></label><label>楼层 <input id="floor" type="number" min="1" max="15" value="2" style="width:44px"></label><label><input id="plan" type="checkbox">正俯视</label>'
 src=src.replace('<label><input id="night"',controls+'<label><input id="night"').replace('height:125px','min-height:150px').replace('max-width:150px','max-width:115px')
 a=src.index('function displayCut(o)');bb=src.index('window.render=async function',a)
 src=src[:a]+'''function displayCut(o){
 const key=JSON.stringify([o.cutY??null,o.minY??null,o.bounds??null]);if(key===currentCut)return;
 if(opaque!==originalOpaque){gl.deleteVertexArray(opaque.vao);gl.deleteBuffer(opaque.buf)}
 if(glass!==originalGlass){gl.deleteVertexArray(glass.vao);gl.deleteBuffer(glass.buf)}
 const filter=m=>{if(o.cutY==null&&o.minY==null&&!o.bounds)return m;let out=[];
 for(let i=0;i<m.data.length;i+=30){let keep=true;for(let k of [0,10,20]){const x=m.data[i+k],y=m.data[i+k+1],z=m.data[i+k+2];if((o.cutY!=null&&y>o.cutY)||(o.minY!=null&&y<o.minY)||(o.bounds&&(x<o.bounds[0]||z<o.bounds[1]||x>o.bounds[2]||z>o.bounds[3])))keep=false;}if(keep)for(let j=0;j<30;j++)out.push(m.data[i+j]);}return mesh(new Float32Array(out));};opaque=filter(originalOpaque);glass=filter(originalGlass);currentCut=key;
 }
 '''+src[bb:]
 a=src.index('let pending=false;function update()');bb=src.index("for(const el of document.querySelectorAll('input,select'))",a)
 updater='''const TOWERS=__TOWERS__;
let pending=false;function update(){if(!window.ready||pending)return;pending=true;requestAnimationFrame(async()=>{try{const yaw=Number(document.getElementById('yaw').value)*Math.PI/180,zoom=Number(document.getElementById('zoom').value),mode=document.getElementById('mode').value,width=Math.min(1280,innerWidth),height=Math.max(300,innerHeight-document.getElementById('controls').offsetHeight);let target=[80,32,83],spanZ=Math.max(195,265*height/width)/zoom,rise=150,dist=330,extra={};const t=TOWERS.find(t=>t.id===document.getElementById('tower').value);document.getElementById('floor').max=t.storeys;let f=Math.max(1,Math.min(t.storeys,Number(document.getElementById('floor').value)||1));document.getElementById('floor').value=f;
if(mode==='garden'){target=[80,5,77];spanZ=Math.max(90,140*height/width)/zoom;rise=115;extra={cutY:17.99}}
if(mode==='tower'){target=[t.x+t.w/2,3+t.storeys*2.5,t.z+t.d/2];spanZ=Math.max(t.storeys*5+20,(t.w+t.d)*height/width)/zoom;rise=30;dist=170;extra={bounds:[t.x-3,t.z-3,t.x+t.w+3,t.z+t.d+4]}}
if(mode==='floor'){const fy=3+(f-1)*5;target=[t.x+t.w/2,fy+1,t.z+t.d/2];spanZ=Math.max(34,(t.w+10)*height/width)/zoom;rise=170;dist=160;extra={cutY:fy+2.95,minY:fy-1,bounds:[t.x-3,t.z-3,t.x+t.w+3,t.z+t.d+4]}}
let eye=[target[0]+Math.sin(yaw)*dist,target[1]+rise,target[2]+Math.cos(yaw)*dist];if(mode==='top'){target=[80,3,83];eye=[80,430,83];spanZ=Math.max(177,170*height/width)/zoom}if(document.getElementById('plan').checked&&['floor','tower','garden'].includes(mode))eye=[target[0],430,target[2]];
await window.render({width,height,spanZ,spanX:spanZ*width/height,eye,target,ortho:true,night:document.getElementById('night').checked,concept:false,...extra});window.lastMode=mode;window.lastFloor=f;document.getElementById('msg').textContent='最终 NBT · '+(mode==='floor'?t.id+' / '+f+'F · ':'')+'拖动旋转；格栅、材质与灯光为近似显示';}catch(e){window.error=e.stack;document.getElementById('msg').textContent='实时查看不可用：'+e.message}pending=false})}
'''.replace('__TOWERS__',json.dumps(PAR['towers']))
 src=src[:a]+updater+src[bb:]
 src=src.replace("body{margin:0;background:#142f3c", "body{margin:0;background:#293c34")
 src=src.replace('</style>','body,select,input,button{font-family:"Noto Sans CJK SC",system-ui,sans-serif}</style>',1)
 return src
def building(v):
 body='<div class="tags"><span class="tag">两排 · 每栋后退 10 格</span><span class="tag">暖黄墙 / 红瓦顶</span><span class="tag">部分住户防盗网</span><span class="tag">120 户逐层内饰</span></div>'
 body+='<div class="hero"><img src="'+pic(P/'se_day.png',1800)+'" alt="最终方块模型：六栋平行错列住宅"><p>当前交付 '+RUN+' · 四向图、内饰和交互查看器均源自最终 NBT。</p></div>'
 body+='<div class="stats"><div><span class="stat">6</span><small>塔楼，前三后三</small></div><div><span class="stat">10 / 15</span><small>前排 / 后排楼层</small></div><div><span class="stat">120</span><small>住宅，首层保留住户</small></div><div><span class="stat">10 格</span><small>从左到右逐栋后退</small></div></div>'
 body+=section('layout','01','让组团沿斜向展开','<div class="grid"><div>'+site_svg()+'</div><div class="card"><h3>两排平行，不再排成正方阵</h3><p>每排从左向右依次向北退 10 格；楼栋保持正交，花园和步道顺着斜向展开。前后两排的住宅数量和层数保持不变。</p>'+table(['楼栋','层数 / 每层住户','起点 Z'],[[t['id'],str(t['storeys'])+' 层 / '+str(t['units_per_floor'])+' 户',t['z']] for t in PAR['towers']])+'<p>每栋有单独门厅、一个静态电梯核心和两格宽楼梯。全场范围 160 × 86 × 166 格；Z 越小越靠北。</p></div></div>')
 body+=section('views','02','同一座住区的日与夜','<div class="controls"><label>方向 <select id="face"><option value="se">东南</option><option value="sw">西南</option><option value="ne">东北</option><option value="nw">西北</option></select></label><label><input type="checkbox" id="nightToggle"> 夜景</label></div><figure class="wide"><img id="mainView" src="'+pic(P/'se_day.png')+'" alt="四向等框日夜预览"><figcaption><b>41 / 120 户亮灯，公共交通区保留灯光</b><span>247 个发光方块；室内灯嵌在吊顶层。冷暖是材料观感，原版不产生真实 RGB 彩光。</span></figcaption></figure>')
 body+=section('interactive','03','旋转、单栋与逐层查看','<p>选择“逐层内饰”，可查看任一栋的第 1–10 / 15 层；勾选正俯视看平面。三维查看需要浏览器支持 WebGL2，首次加载几何会稍慢。</p><button id="load3d" class="primary">打开交互模型</button><div id="threeD"></div>')
 body+=section('facade','04','同一年代，留下不同住户的痕迹','<div class="grid">'+fig('facade_detail.png','防盗网、封窗与空调','突出笼式 141 组、薄网式 101 组、无网 463 组；含 45 组公共窗。')+fig('entry_detail.png','朝花园的独立门厅','门厅、雨棚、信报与短坐席；入户和楼梯通道分开安排。')+'</div><p>阳台有开放与封闭两类，玻璃在透明、浅蓝和灰色之间按住户变化，花盆只出现在部分阳台。格栅预览补了开孔；NBT 使用真实 iron_bars，网格显示并非游戏纹理。</p>')
 body+=section('homes','05','120 户都建立住宅分区','<div class="grid">'+fig('A_plan.png','A 型：一梯一户 · 二层回读平面','两间卧室、起居、餐区、厨房和卫生间；中央通道连接入户。')+fig('B_plan.png','B 型：一梯两户 · 二层回读平面','左右两户共用电梯和楼梯，住宅入口独立。')+fig('A_cut.png','A 型内饰切层','床形、收纳、沙发、餐桌、厨房及卫浴为方块装饰。')+fig('B_cut.png','B 型内饰切层','每层保留相同功能关系；床品和亮灯按住户变化。')+'</div><div class="note">共 630 个功能区、1,110 组家具模块。家具是外观模型，床形不能直接睡觉；电梯为静态示意。实际游戏碰撞、上下楼手感和导入仍待测试。</div>')
 body+=section('garden','06','中间留给共享花园','<div class="grid">'+fig('garden_day.png','环路、草坪、水池与廊架','上层切除用于看清园林；不代表只建低层。')+fig('garden_night.png','同机位园林夜景','路径与入口提供少量引导光，园林保持暗面。')+'</div><p>连续园路连接六个门厅；慢行环线、树荫座椅、廊架和小活动角各有位置。小水池作为园林节点，不占主要行走线。</p>')
 body+=section('drawings','07','总图、立面与楼板分解','<div class="grid">'+fig('top_day.png','真俯视 · 完整屋顶','六栋的 10 格退让可从顶视比较。')+fig('site_plan.png','低位总图 · 入口和园路','同一最终 NBT 在低标高截切。')+fig('front_elevation.png','南向立面','前排 10 层，后排 15 层。')+fig('back_elevation.png','北向立面','核心与住宅窗洞保持不同节奏。')+fig('west_elevation.png','西向立面')+fig('east_elevation.png','东向立面')+fig('section.png','A1 剖切','楼梯、楼板及楼层关系。')+fig('exploded.png','A1 二层组件分解','地板 → 房间层 → 嵌灯吊顶 → 上层地板；只为展示平移组件。',P.parent/(RUN+'_exploded'))+'</div>')
 body+=section('delivery','08','成果与核对','<p>最终模型 '+f'{MAN["non_air_blocks"]:,}'+' 个非空气方块，705 组窗。NBT 独立回读一致，17 项几何、3 项通行／模块和 2 项退让检查通过。</p>'+dl(R/'building.nbt','下载 NBT')+dl(R/'params_used.json','设计参数')+dl(R/'validation.json','几何检查')+dl(R/'access_validation.json','通行补充检查')+'<details><summary>NBT 导入说明</summary><p>Java Structure NBT，DataVersion 3955。范围 160 × 86 × 166 格，使用稀疏输出、不写入空气；请放在空场地。超出原版结构方块常规尺寸的导入器支持尚未在游戏中验证。</p><pre>SHA256 '+MAN['sha256']+'</pre></details>')
 views={q+'_'+m:pic(P/(q+'_'+m+'.png')) for q in ['se','sw','ne','nw'] for m in ['day','night']}
 script='const VIEWS='+json.dumps(views)+';const VIEWER='+json.dumps(v)+';function swap(){document.getElementById("mainView").src=VIEWS[document.getElementById("face").value+"_"+(document.getElementById("nightToggle").checked?"night":"day")]}document.getElementById("face").addEventListener("change",swap);document.getElementById("nightToggle").addEventListener("change",swap);document.getElementById("load3d").addEventListener("click",function(){const f=document.createElement("iframe");f.title="千禧年住宅交互模型";f.srcdoc=VIEWER;document.getElementById("threeD").append(f);this.remove()});'
