def process():
 body='<div class="dark"><h2>从参考意向，到可回读的方块。</h2><p>本次是原创建筑。用户照片提供年代和住户细节，生成图提供总体意向；楼层、户型、楼梯和场地坐标由明确的规则构建。</p></div>'
 body+=section('sources','01','本次实际使用了什么资料','<div class="grid">'+fig('style_photo.jpg','用户提供的风格照片','采用暖黄墙、红瓦、混合防盗网、空调与盆栽；不复制公交站或楼层数。',C/'input')+fig('approved_reference.png','此前确认的生成参考图','六栋、两种层数、中央花园的视觉意向；不是测绘依据。',C/'input')+'</div><p>本次建造没有新增网络检索，没有来源网址可列。原图与 SHA256 记录在 input/provenance.json。随后用户补充“每栋后退 10 格”，最终总图优先执行这一明确尺寸。</p>')
 body+=section('contract','02','先固定可执行的空间约束',table(['约束','最终落实'],[['塔楼','A1–A3：10层、一梯一户；B1–B3：15层、一梯两户'],['总量','120户，首层同样保留住宅；门厅占独立公共核心'],['平行错列','A 起点 Z=118/108/98，B=31/21/11；两排逐栋退10格'],['尺度适配','平面约1格/米；层高5格＝3格净空＋2格楼板/灯光；不按生成图像素强行折算'],['灯光','10层不套用“低于10层全亮”；41户亮灯，公共交通有灯'],['功能','每户两卧室、起居、厨房、卫浴；部分户型另分餐区'],['建造边界','静态电梯、装饰家具、开放式门洞；未完成真实游戏验收']]))
 body+=section('geometry','03','参考盒与同坐标几何','<div class="grid"><div>'+site_svg()+'</div><div>'+box_svg()+'</div></div><p>每栋用 8 个角点的包围盒约束宽深高，窗洞、户型、交通和屋顶共用坐标。退让阶段刚性平移楼栋，未剪切住宅；园路按斜线重排。这里没有执行自动图像分割、相机恢复、三维重建或模型训练。</p>')
 body+=section('skills','04','skill 实际做到了哪一步',table(['环节','实际产物','执行边界'],[['无实物设计','两种户型、6个建筑交接输入、园林关系','原创规则，不冒充实物证据'],['内饰 / HAF0.4编译','630个功能区、1,110个模块的边界及接近面','编译器只出计划；案例消费者实际放块'],['建筑引擎','楼板、窗、铁栅栏、阳台、家具和69段楼层间楼梯','专用案例适配器，不宣称通用图片自动建造'],['灯光 / 园林','下层嵌灯、按户亮灯、完整步道和停留节点','材料冷暖不代表彩光，照明并非游戏实测'],['NBT回读','导出后独立解析；从最终NBT生成24张固定视图','不是用生成图充当建造成果'],['同源分解','A1二层的原方块按组件标高平移','分解图有单独派生NBT和映射；最终NBT没有拉开楼板'],['交互 / 交付','逐栋、逐层、日夜和俯视；两份独立HTML','浏览器WebGL2与纹理近似显示']]))
 body+=section('facade','05','住户变化怎样进入模型','<div class="grid">'+fig('facade_detail.png','最终窗区近景')+'<div class="card"><h3>按住户分配，再允许局部例外</h3><p>稳定的住户 ID 决定玻璃色、是否装防盗网、封阳台和盆栽。每个窗组保留所属住户与窗洞坐标，避免逐方块随机噪声。</p><p>705组窗：突出笼式141，薄网式101，无网463（含45组公共窗）。所有卧室与起居窗后都有实际分区。</p><p>近景铁网使用额外的细杆网格近似原版透明贴图；导出的方块仍为 iron_bars。它改善离线可读性，不改变游戏材质。</p></div></div>')
 rounds=[['R01','266,527','六栋及120户首次建造；35个路径单元碰到空调、窗网或设施','保留失败检查与首次图'],['R02','266,548','移开外围路径和活动设施；厨房改独立接入起居；格栅开孔预览','17项＋3项通过；尚未按新要求退让'],['R03','275,401','新增每栋后退10格，场地加长；廊架一根柱碰斜向环路','保留失败样点'],['R04','275,401','廊架调整，另一侧柱碰中间步道','保留失败样点'],['R05','275,401','廊架落在两条路径之间，通路全部通过','退让已通过'],['R06',str(MAN['non_air_blocks']),'前后排横向间距统一50格，形成严格平行的退让线','当前交付；用户视觉与游戏待验']]
 body+=section('iterations','06','真实迭代记录',table(['版本','非空气方块','变化 / 发现','状态'],rounds)+'<p>旧 run、输入、失败记录与代码快照均保留。R01 的初始总览还有裁框不足，后续改为统一等框四向图；不把不同机位当作像素对比。</p>')
 body+=section('checks','07','验证与未验证',table(['检查','结果'],[[r['id'],'<span class="pill">'+r['status']+'</span>'] for r in VAL['checks']+ACC['checks']+LAY['checks']])+'<p>额外核对两格宽楼梯样带、75个楼层公共平台到120户的连通、1,110组家具的最终存活计数。通行检查使用方块占用与两格净空，不能替代原版楼梯碰撞或游戏寻路。</p><p>当前共享核心未修改。本案例的检查结果与历史回归、用户审美认可、真实游戏验收分别记录；未测部分保持 pending。</p>'+dl(R/'validation.json','几何检查原文')+dl(R/'access_validation.json','补充检查原文'))
 body+=section('next','08','下一步先看这三件事','<ol><li>用俯视和旋转视图确认“每栋后退10格”的斜向关系，以及花园在两排之间的比例。</li><li>近看无光影风格的窗区：确认防盗网密度、暖黄墙比例及屋顶是否符合你要的千禧年感。</li><li>导入游戏检查入口、楼梯、灯光与大尺寸NBT支持；若要居住功能，再把装饰床形和静态电梯换成真实可用组件。</li></ol>')
 files=['params_used.json','design_handoffs.json','resolved_plans.json','units.json','floor_levels.json','stairs.json','module_consumption.json','lamps.json','paths.json','windows.json','manifest.json']
 body+=section('files','09','文件、参数与复跑',table(['文件','内容'],[['Estate.html','成果、日夜、全楼栋逐层交互和NBT下载'],['Estate_Process.html','本文件：来源、空间规则、能力边界和真实迭代'],['Estate.nbt','最终稀疏Java结构NBT'],['Estate.zip','本案例输入、源代码、六轮run、检查、最终视图和两个HTML']])+'<p>'+''.join(dl(R/f) for f in files)+'</p><pre>python -m pip install numpy Pillow fonttools\npython tools/agent.py --case millennium_estate --run replay\npython cases/millennium_estate/src/validate_case.py --run replay\npython cases/millennium_estate/src/validate_access.py --run replay\npython cases/millennium_estate/src/validate_layout.py --run replay\npython cases/millennium_estate/src/render_case.py --run replay\npython cases/millennium_estate/src/render_exploded.py --run replay</pre><p>Linux 渲染需要 libEGL。新 run 不覆盖旧 run。案例适配器与格栅显示在本案例 src 下；未升级全局技能版本。</p><details><summary>查看建造代码</summary><pre>'+esc((C/'src/build_case.py').read_text())+'</pre></details><details><summary>查看10格退让代码</summary><pre>'+esc((C/'src/layout.py').read_text())+'</pre></details>')
 return shell('从意向到住区','千禧年住宅组团的完整制作记录，与建筑成果文件分开保存。',[('sources','输入'),('contract','约束'),('geometry','参考盒'),('skills','能力'),('iterations','迭代'),('checks','检查'),('files','文件')],body)
